from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from djmoney.money import Money
from .models import MultiCurrencyWallet

class WalletDebitTransferView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        wallet_id = request.data.get("wallet_id")
        amount_val = request.data.get("amount")
        currency = request.data.get("currency", "USD")

        # Enforce that the wallet is owned by the authenticated caller
        wallet = MultiCurrencyWallet.objects.filter(
            id=wallet_id,
            owner=request.user,
            balance_currency=currency
        ).first()
        if not wallet:
            return Response({"error": "Wallet not found for currency"}, status=status.HTTP_404_NOT_FOUND)

        debit = Money(amount_val, currency)
        if wallet.balance < debit:
            return Response({"error": "Insufficient balance"}, status=status.HTTP_400_BAD_REQUEST)

        wallet.balance -= debit
        wallet.save(update_fields=['balance'])
        return Response({"status": "Debited", "new_balance": str(wallet.balance)})
